List<int> candidate(String parenString) {
  int parseParenGroup(String s) {
    int depth = 0;
    int maxDepth = 0;
    for (int i = 0; i < s.length; i++) {
      String c = s[i];
      if (c == '(') {
        depth += 1;
        maxDepth = depth > maxDepth ? depth : maxDepth;
      } else {
        depth -= 1;
      }
    }
    return maxDepth;
  }

  return parenString
      .split(' ')
      .where((x) => x.isNotEmpty)
      .map((x) => parseParenGroup(x))
      .toList();
}

