  final implementation = candidate;

  expect(implementation(1), 2);
  expect(implementation(2), 3);
  expect(implementation(3), 5);
  expect(implementation(4), 13);
  expect(implementation(5), 89);
  expect(implementation(6), 233);
  expect(implementation(7), 1597);
  expect(implementation(8), 28657);
  expect(implementation(9), 514229);
  expect(implementation(10), 433494437);
}

void expect(dynamic a, dynamic b) {
  if (a == b) return;

  if (a is List && b is List) {
    expectList(a, b);
  } else if (a is Map && b is Map) {
    expectMap(a, b);
  } else {
    throw '$a != $b';
  }
}

void expectList(List a, List b) {
  if (a.length != b.length) throw 'list lengths are not equal';

  for (var i = 0; i < a.length; i++) {
    expect(a[i], b[i]);
  }
}

void expectMap(Map a, Map b) {
  if (a.length != b.length) throw 'map lengths are not equal';

  for (var key in a.keys) {
    expect(a[key], b[key]);
  }
}

