@pragma('vm:entry-point')
bool candidate(List<num> l) {
  List<num> sortedList = List.from(l)..sort();
  List<num> reverseSortedList = List.from(l)..sort((a, b) => b.compareTo(a));

  bool isIncreasing = true;
  bool isDecreasing = true;

  for (int i = 0; i < l.length; i++) {
    if (l[i] != sortedList[i]) {
      isIncreasing = false;
    }
    if (l[i] != reverseSortedList[i]) {
      isDecreasing = false;
    }
  }

  return isIncreasing || isDecreasing;
}

tests:
void main() {
  final implementation = candidate;

  expect(implementation([1, 2, 4, 10]), true);
  expect(implementation([1, 2, 4, 20]), true);
  expect(implementation([1, 20, 4, 10]), false);
  expect(implementation([4, 1, 0, -10]), true);
  expect(implementation([4, 1, 1, 0]), true);
  expect(implementation([1, 2, 3, 2, 5, 60]), false);
  expect(implementation([1, 2, 3, 4, 5, 60]), true);
  expect(implementation([9, 9, 9, 9]), true);
